using ClosedXML.Excel;
using iTextSharp.text;
using iTextSharp.text.pdf;
using Microsoft.EntityFrameworkCore;
using QL_KhachSan.Models;
using System.Globalization;
using System.IO;
using PdfFont = iTextSharp.text.Font;
using PdfParagraph = iTextSharp.text.Paragraph;
using PdfRectangle = iTextSharp.text.Rectangle;

namespace QL_KhachSan.HoaDon;

internal sealed class FormHoaDon : Form
{
    private readonly string _maHD; private readonly Label _heading = new(); private readonly DataGridView _services = HotelUi.Grid(); private readonly Label _info = new(); private decimal _total;
    private sealed record Service(string MaDV, string TenDV, int SoLuong, decimal DonGia, decimal ThanhTien);
    private sealed record Invoice(string MaHD, DateTime? NgHD, string MaCTDP, string MaPH, string TenLP, string TenKH, string TenNV, DateTime CheckIn, DateTime CheckOut, decimal TienPhong, decimal TriGia, string TrangThai);
    public FormHoaDon(string maHD)
    {
        _maHD = maHD; Text = "Hóa đơn thanh toán"; StartPosition = FormStartPosition.CenterParent; Size = new Size(900, 700); MinimumSize = new Size(760, 580); BackColor = Color.White;
        var root = new TableLayoutPanel { Dock = DockStyle.Fill, Padding = new Padding(22), ColumnCount = 1, RowCount = 4 }; root.RowStyles.Add(new RowStyle(SizeType.Absolute, 48)); root.RowStyles.Add(new RowStyle(SizeType.Absolute, 190)); root.RowStyles.Add(new RowStyle(SizeType.Percent, 100)); root.RowStyles.Add(new RowStyle(SizeType.Absolute, 66));
        _heading.Text = "HÓA ĐƠN THANH TOÁN"; _heading.Dock = DockStyle.Fill; _heading.TextAlign = ContentAlignment.MiddleCenter; _heading.Font = new System.Drawing.Font("Segoe UI", 20, System.Drawing.FontStyle.Bold); _heading.ForeColor = HotelUi.DarkGreen; root.Controls.Add(_heading, 0, 0);
        _info.Dock = DockStyle.Fill; _info.Font = new System.Drawing.Font("Segoe UI", 11); _info.Padding = new Padding(10); root.Controls.Add(_info, 0, 1);
        _services.Columns.Add("MaDV", "Mã DV"); _services.Columns.Add("TenDV", "Tên dịch vụ"); _services.Columns.Add("SL", "Số lượng"); _services.Columns.Add("DonGia", "Đơn giá"); _services.Columns.Add("ThanhTien", "Thành tiền"); _services.Columns[3].DefaultCellStyle.Format = _services.Columns[4].DefaultCellStyle.Format = "N0"; root.Controls.Add(_services, 0, 2);
        var buttons = new FlowLayoutPanel { Dock = DockStyle.Fill, FlowDirection = FlowDirection.RightToLeft }; var close = HotelUi.Button("Đóng"); var pdf = HotelUi.Button("Xuất PDF", true); close.Click += (_, _) => Close(); pdf.Click += (_, _) => ExportPdf(); buttons.Controls.AddRange([close, pdf]); root.Controls.Add(buttons, 0, 3); Controls.Add(root); Load += (_, _) => LoadData();
    }
    private void LoadData() { try { using var db = new HotelManagementContext(); var h = db.HoaDons.AsNoTracking().Where(x => x.MaHd == _maHD && x.DaXoa != true).Select(x => new Invoice(x.MaHd, x.NgHd, x.MaCtdp, x.MaCtdpNavigation.MaPh, x.MaCtdpNavigation.MaPhNavigation.MaLphNavigation.TenLph, x.MaCtdpNavigation.MaPtNavigation.MaKhNavigation.TenKh, x.MaNvNavigation.TenNv, x.MaCtdpNavigation.CheckIn, x.MaCtdpNavigation.CheckOut, x.MaCtdpNavigation.ThanhTien ?? 0, x.TriGia ?? 0, x.TrangThai)).FirstOrDefault(); if (h is null) { MessageBox.Show("Không tìm thấy hóa đơn."); Close(); return; } _total = h.TriGia; _info.Text = $"Mã hóa đơn: {h.MaHD}\nNgày lập: {h.NgHD:dd/MM/yyyy HH:mm}\nMã chi tiết thuê: {h.MaCTDP}    Phòng: {h.MaPH} ({h.TenLP})\nKhách hàng: {h.TenKH}\nNhân viên: {h.TenNV}\nThời gian: {h.CheckIn:dd/MM/yyyy HH:mm} - {h.CheckOut:dd/MM/yyyy HH:mm}\nTiền phòng: {h.TienPhong:N0}    Trạng thái: {h.TrangThai}\nTỔNG TRỊ GIÁ: {h.TriGia:N0}"; var rows = db.Ctdvs.AsNoTracking().Where(v => v.MaCtdp == h.MaCTDP && v.DaXoa != true).Include(v => v.MaDvNavigation).OrderBy(v => v.MaDv).ToList(); _services.Rows.Clear(); foreach (var x in rows) _services.Rows.Add(x.MaDv, x.MaDvNavigation.TenDv, x.Sl, x.DonGia, x.ThanhTien ?? x.Sl * x.DonGia); } catch (Exception ex) { MessageBox.Show("Lỗi khi tải hóa đơn: " + ex.GetBaseException().Message); } }
    private void ExportPdf() { using var save = new SaveFileDialog { Filter = "PDF (*.pdf)|*.pdf", FileName = $"HoaDon_{_maHD}.pdf", Title = "Xuất hóa đơn" }; if (save.ShowDialog(this) != DialogResult.OK) return; try { using var stream = new FileStream(save.FileName, FileMode.Create, FileAccess.Write); using var doc = new Document(PageSize.A4, 42, 42, 42, 42); PdfWriter.GetInstance(doc, stream); doc.Open(); var bf = BaseFont.CreateFont(@"C:\Windows\Fonts\arial.ttf", BaseFont.IDENTITY_H, BaseFont.EMBEDDED); var titleFont = new PdfFont(bf, 18, PdfFont.BOLD); var bodyFont = new PdfFont(bf, 11); doc.Add(new PdfParagraph("HOTEL MANAGEMENT", new PdfFont(bf, 13, PdfFont.BOLD)) { Alignment = Element.ALIGN_CENTER }); doc.Add(new PdfParagraph("HÓA ĐƠN THANH TOÁN", titleFont) { Alignment = Element.ALIGN_CENTER, SpacingAfter = 18 }); doc.Add(new PdfParagraph(_info.Text, bodyFont) { SpacingAfter = 12 }); var table = new PdfPTable(4) { WidthPercentage = 100 }; table.SetWidths([38, 12, 18, 32]); foreach (var head in new[] { "Tên dịch vụ", "Đơn giá", "Số lượng", "Thành tiền" }) table.AddCell(new PdfPCell(new Phrase(head, new PdfFont(bf, 10, PdfFont.BOLD))) { BackgroundColor = new BaseColor(225, 239, 233), Padding = 6 }); foreach (DataGridViewRow r in _services.Rows) foreach (var c in new[] { 1, 3, 2, 4 }) table.AddCell(new PdfPCell(new Phrase(r.Cells[c].Value?.ToString() ?? "", bodyFont)) { Padding = 5 }); doc.Add(table); var total = new PdfParagraph($"Tổng thanh toán: {_total:N0} VNĐ", new PdfFont(bf, 14, PdfFont.BOLD)) { Alignment = Element.ALIGN_RIGHT, SpacingBefore = 16 }; doc.Add(total); doc.Add(new PdfParagraph("Cảm ơn quý khách đã sử dụng dịch vụ!", bodyFont) { Alignment = Element.ALIGN_CENTER, SpacingBefore = 30 }); doc.Close(); using var db = new HotelManagementContext(); var hd = db.HoaDons.FirstOrDefault(x => x.MaHd == _maHD && x.DaXoa != true); if (hd is not null && hd.TrangThai != "Đã thanh toán") { hd.TrangThai = "Đã thanh toán"; db.SaveChanges(); } MessageBox.Show("Xuất hóa đơn PDF thành công.", "Thông báo", MessageBoxButtons.OK, MessageBoxIcon.Information); } catch (Exception ex) { MessageBox.Show("Lỗi khi xuất hóa đơn PDF: " + ex.GetBaseException().Message, "Lỗi", MessageBoxButtons.OK, MessageBoxIcon.Error); } }
}
